t = 10 ** 6 + 1
prime = [0] * t
k = [0] * t

def sieve():
	for i in range(1, t):
		k[i] = i
	for i in range(2, t):
		if prime[i] == 0:
			for j in range(i, t, i):
				prime[j] = 1
				while k[j] % (i * i) == 0:
					k[j] /= i * i

def count_pair(arr, n):
	freq = {}
	for i in range(n):
		if k[arr[i]] in freq.keys():
			freq[k[arr[i]]] += 1
		else:
			freq[k[arr[i]]] = 1
	res = 0
	for i in freq:
		res += freq[i] * (freq[i] - 1) // 2
	return res
sieve()
for _ in range(int(input())):
	n = int(input())
	arr = list(map(int, input().split()))
	temp = count_pair(arr, n)
	all_pair = n * (n - 1) // 2
	print(all_pair - temp)
